def stamp(row, ts=None):
    if ts is None:
        ts = datetime.now()
    row["ts"] = ts
    return row

def make_multiplier(k):
    def mul(x):
        return x * k
    return mul

double = make_multiplier(2)
double(21)  # 42

def make_counter():
    n = 0
    def nxt():
        n += 1   # UnboundLocalError
        return n
    return nxt

def clean(row):
    return {**row, "city": row["city"].strip().title()}

